using System.Net;using System.Net.Sockets;using System.Text.Json;using System.Buffers.Binary;using System.Diagnostics;
namespace P06;
public sealed partial class ClientForm {
 async Task ReceiveLoadDemo(){
  var rows=Json.Read(Path.Combine(stageRoot,"fixtures/combat-initialization.json")).GetProperty("rows").EnumerateArray().Where(x=>x.I("generation")==1).Select(x=>x.GetProperty("packet")).ToArray();byte[] seedBody=Convert.FromHexString(rows[0].S("bodyHex"));var initial=rows.Skip(1).Select(x=>Convert.FromHexString(x.S("plainHex"))).Take(12).ToArray();
  using var stop=new CancellationTokenSource();var listener=new TcpListener(IPAddress.Loopback,42062);listener.Start();var selected=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);int transmitted=0,received=0,ticks=0,paintBefore=paintCount;long expectedSequence=0;bool order=true;var watch=Stopwatch.StartNew();long lastTick=0,maxGap=0;var checkpoints=new List<object>();
  using var responsiveness=new System.Windows.Forms.Timer{Interval=20};responsiveness.Tick+=(_,_)=>{long now=watch.ElapsedMilliseconds;if(lastTick!=0)maxGap=Math.Max(maxGap,now-lastTick);lastTick=now;ticks++;};responsiveness.Start();
  login.PacketReceived+=obj=>{var p=JsonSerializer.SerializeToElement(obj);if(!p.TryGetProperty("plainHex",out var h))return;long seq=p.GetProperty("sequence").GetInt64();if(seq!=++expectedSequence)order=false;var raw=Convert.FromHexString(h.GetString()!);if(raw[0]==123){if(BinaryPrimitives.ReadUInt32LittleEndian(raw.AsSpan(1))!=(uint)(++received))order=false;}};
  var peer=Task.Run(async()=>{using var client=await listener.AcceptTcpClientAsync(stop.Token);var stream=client.GetStream();await stream.WriteAsync(LoginFrames.Wrap(seedBody),stop.Token);var cipher=new LoginCipher(LoginPackets.Seed(seedBody));async Task Send(byte[] b)=>await stream.WriteAsync(LoginFrames.Wrap(cipher.Transform(b,true)),stop.Token);foreach(var b in initial.Take(3))await Send(b);await selected.Task;foreach(var b in initial.Skip(3))await Send(b);for(int i=1;i<=24000;i++){byte[] time=new byte[8];time[0]=123;BinaryPrimitives.WriteUInt32LittleEndian(time.AsSpan(1),(uint)i);await Send(time);Interlocked.Increment(ref transmitted);}await release.Task;});
  Task? running=null;
  try{await Until(()=>webReady,15000);running=login.Run(42062,"jar-d287-client2","synthetic","synthetic",10000);await Until(()=>login.State==LoginState.CharacterList,10000);await login.SelectCharacter(login.Characters.Single().Name);selected.SetResult();await Until(()=>login.State==LoginState.InWorld&&received>=1000,20000);CaptureEvidence("load-active");checkpoints.Add(new{phase="active",received,ticks,paintCount});
   await FocusWebInput();OnKeyDown(new KeyEventArgs(Keys.G));OnKeyUp(new KeyEventArgs(Keys.G));if(GameInputAllowed||login.World.AttackReports!=0)throw new Exception("focus isolation under load");checkpoints.Add(new{phase="input-focus",received,ticks,paintCount});
   await web!.ExecuteScriptAsync("document.getElementById('game').click()");await Until(()=>GameInputAllowed,5000);await Until(()=>received>=5000,30000);RefreshScene();Update();CaptureEvidence("load-before-cancel");if(ticks<5||paintCount-paintBefore<2||maxGap>1000||!order)throw new Exception("UI timer/paint/sequence did not progress");
   long cancelStart=watch.ElapsedMilliseconds;login.Cancel();await running;if(watch.ElapsedMilliseconds-cancelStart>3000||login.World.Actor!=null||login.State!=LoginState.Cancelled)throw new Exception("cancel under load failed");checkpoints.Add(new{phase="cancelled",received,ticks,paintCount});
   Json.Save(Path.Combine(evidence!,"receive-load-result.json"),new{status="pass",kind="synthetic loopback TCP replay initialization plus ordered high-rate time packets; actual WinForms/WebView2; not original-server combat",received,transmitted,expectedSequence,order,ticks,paints=paintCount-paintBefore,maxTimerGapMs=maxGap,cancelMs=watch.ElapsedMilliseconds-cancelStart,elapsedMs=watch.ElapsedMilliseconds,checkpoints});
  }catch(Exception ex){NetworkExitCode=5;Json.Save(Path.Combine(evidence!,"receive-load-result.json"),new{status="fail",error=ex.ToString(),received,transmitted,ticks,paintCount,order,snapshot=login.Snapshot()});}
  finally{login.Cancel();stop.Cancel();release.TrySetResult();listener.Stop();try{await peer;}catch(Exception ex)when(ex is IOException or OperationCanceledException or SocketException){}Close();}
 }
}
